CREATE OR REPLACE FUNCTION public.assign_pilot_product_to_zone(p_zone_id uuid, p_product_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid := (select auth.uid()); v_org uuid; v_store uuid; v_unit text; v_sort integer;
begin
  select z.organization_id,z.store_id,p.count_unit into v_org,v_store,v_unit
  from public.count_zones z join public.products p on p.id=p_product_id and p.organization_id=z.organization_id
  where z.id=p_zone_id and z.is_active and p.is_active;
  if v_store is null or not private.has_active_store_role(v_store,array['ADMIN','SUPERVISOR']::public.app_role[]) then
    raise exception using errcode='42501',message='STORE_MANAGER_REQUIRED';
  end if;
  select coalesce(max(sort_order),-1)+1 into v_sort from public.zone_products where zone_id=p_zone_id;
  insert into public.zone_products(zone_id,product_id,sort_order,count_unit)
  values(p_zone_id,p_product_id,v_sort,v_unit) on conflict(zone_id,product_id) do nothing;
  insert into public.audit_logs(organization_id,entity_type,entity_id,action,new_value,user_id)
  values(v_org,'count_zone',p_zone_id,'PRODUCT_ASSIGNED_TO_ZONE',jsonb_build_object('product_id',p_product_id),v_user);
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_pilot_count_zone(p_session_id uuid, p_zone_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid := (select auth.uid()); v_org uuid; v_store uuid; v_expected integer; v_actual integer;
begin
  select organization_id,store_id into v_org,v_store from public.inventory_count_sessions
  where id=p_session_id and status='IN_PROGRESS';
  if v_store is null or not private.has_active_store_role(v_store,null) then
    raise exception using errcode='42501',message='ACTIVE_STORE_MEMBERSHIP_REQUIRED';
  end if;
  if not exists(select 1 from public.count_zone_progress where session_id=p_session_id and zone_id=p_zone_id and status<>'COMPLETED') then
    raise exception using errcode='22023',message='COUNT_ZONE_NOT_AVAILABLE';
  end if;
  select count(*) into v_expected from public.zone_products where zone_id=p_zone_id;
  select count(*) into v_actual from public.count_drafts where session_id=p_session_id and zone_id=p_zone_id and entered_by=v_user;
  if v_expected=0 or v_actual<>v_expected then raise exception using errcode='22023',message='COUNT_ZONE_INCOMPLETE'; end if;
  insert into public.count_entries(organization_id,session_id,zone_id,product_id,quantity,unit,entered_by,entry_type)
  select organization_id,session_id,zone_id,product_id,quantity,unit,v_user,'INITIAL_COUNT'
  from public.count_drafts where session_id=p_session_id and zone_id=p_zone_id and entered_by=v_user;
  delete from public.count_drafts where session_id=p_session_id and zone_id=p_zone_id and entered_by=v_user;
  update public.count_zone_progress set status='COMPLETED',completed_by=v_user,completed_at=now()
  where session_id=p_session_id and zone_id=p_zone_id;
  insert into public.audit_logs(organization_id,entity_type,entity_id,action,new_value,user_id)
  values(v_org,'inventory_count_session',p_session_id,'COUNT_ZONE_COMPLETED',jsonb_build_object('zone_id',p_zone_id),v_user);

  if not exists(select 1 from public.count_zone_progress where session_id=p_session_id and status<>'COMPLETED') then
    insert into public.inventory_count_discrepancies(
      organization_id,session_id,zone_id,product_id,initial_entry_id,
      previous_quantity,previous_confirmed_at,estimated_quantity,difference,status
    )
    select v_org,p_session_id,(array_agg(e.zone_id order by e.entered_at))[1],e.product_id,(array_agg(e.id order by e.entered_at))[1],
      b.quantity,b.created_at,sum(e.quantity),sum(e.quantity)-b.quantity,'PENDING'
    from public.count_entries e join public.store_product_opening_balances b
      on b.store_id=v_store and b.product_id=e.product_id
    where e.session_id=p_session_id and e.entry_type='INITIAL_COUNT'
    group by e.product_id,b.quantity,b.created_at
    having sum(e.quantity)<>b.quantity
    on conflict(session_id,zone_id,product_id) do nothing;
    update public.inventory_count_sessions set status=case when exists(
      select 1 from public.inventory_count_discrepancies where session_id=p_session_id
    ) then 'REVIEWING' else 'CLOSED' end,completed_at=now() where id=p_session_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_lot_from_receipt_line()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_receipt public.goods_receipts;
  v_store text;
  v_lot_id uuid;
  v_expiry date;
begin
  select * into v_receipt from public.goods_receipts where id = new.receipt_id;
  select b.store_name into v_store from public.receipt_upload_batches b where b.id = v_receipt.source_batch_id;
  if nullif(new.batch_or_expiry, '') ~ '^\d{4}-\d{2}-\d{2}$' then v_expiry := new.batch_or_expiry::date; end if;
  insert into public.inventory_lots (
    organization_id, store_name, product_id, lot_code, original_expiry_date,
    source_type, source_id, created_by
  ) values (
    new.organization_id, coalesce(v_store, '未指定門市'), new.product_id,
    nullif(new.batch_or_expiry, ''), v_expiry, 'GOODS_RECEIPT', new.id, v_receipt.reviewed_by
  ) returning id into v_lot_id;
  insert into public.inventory_lot_events (
    organization_id, lot_id, event_type, preservation_state, quantity, unit,
    occurred_on, source_type, source_id, recorded_by
  ) values (
    new.organization_id, v_lot_id, 'RECEIVED', 'ORIGINAL_EXPIRY', new.quantity, new.unit,
    v_receipt.receipt_date, 'GOODS_RECEIPT', new.id, v_receipt.reviewed_by
  );
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_my_organization(p_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user_id uuid := (select auth.uid()); v_name text := nullif(trim(p_name),''); v_org_id uuid;
begin
 if v_user_id is null then raise exception 'Authentication required'; end if;
 if v_name is null then raise exception 'Organization name is required'; end if;
 if exists(select 1 from public.organization_members where user_id=v_user_id and is_active) then raise exception 'User already belongs to an organization'; end if;
 insert into public.organizations(name) values(v_name) returning id into v_org_id;
 insert into public.organization_members(organization_id,user_id,role,is_active) values(v_org_id,v_user_id,'ADMIN',true);
 insert into public.profiles(id,display_name,organization_id,role,store) values(v_user_id,'',v_org_id,'ADMIN',v_name)
 on conflict(id) do update set organization_id=excluded.organization_id,role=excluded.role,store=excluded.store,updated_at=now();
 return v_org_id;
end; $function$

CREATE OR REPLACE FUNCTION public.create_owner_business(p_organization_name text, p_business_type text, p_store_name text, p_store_code text, p_staff_login_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := (select auth.uid());
  v_user auth.users%rowtype;
  v_org_name text := nullif(btrim(p_organization_name), '');
  v_store_name text := nullif(btrim(p_store_name), '');
  v_store_code text := btrim(p_store_code);
  v_org_id uuid;
  v_store_id uuid;
begin
  if v_user_id is null then raise exception using errcode = '28000', message = 'OWNER_AUTH_REQUIRED'; end if;

  select * into v_user from auth.users where id = v_user_id;
  if v_user.email_confirmed_at is null then
    raise exception using errcode = '28000', message = 'OWNER_EMAIL_NOT_VERIFIED';
  end if;
  if coalesce(v_user.raw_user_meta_data ->> 'account_type', '') <> 'OWNER_REGISTRATION' then
    raise exception using errcode = '42501', message = 'OWNER_REGISTRATION_REQUIRED';
  end if;
  if exists (select 1 from public.organization_members where user_id = v_user_id and is_active) then
    raise exception using errcode = '23505', message = 'OWNER_ALREADY_ONBOARDED';
  end if;
  if v_org_name is null or v_store_name is null then
    raise exception using errcode = '22023', message = 'OWNER_BUSINESS_NAME_REQUIRED';
  end if;
  if p_business_type not in ('SINGLE_RESTAURANT', 'CHAIN_RESTAURANT') then
    raise exception using errcode = '22023', message = 'OWNER_BUSINESS_TYPE_INVALID';
  end if;
  if v_store_code !~ '^[A-Za-z0-9][A-Za-z0-9_-]{1,31}$' then
    raise exception using errcode = '22023', message = 'OWNER_STORE_CODE_INVALID';
  end if;
  if p_staff_login_mode not in ('NAME_OR_NICKNAME', 'EMPLOYEE_NUMBER') then
    raise exception using errcode = '22023', message = 'OWNER_LOGIN_MODE_INVALID';
  end if;

  insert into public.organizations(name, business_type, owner_user_id)
  values (v_org_name, p_business_type, v_user_id)
  returning id into v_org_id;

  update public.profiles set
    organization_id = v_org_id,
    display_name = coalesce(nullif(btrim(v_user.raw_user_meta_data ->> 'display_name'), ''), split_part(v_user.email, '@', 1)),
    role = 'ADMIN', store = v_store_name, updated_at = now()
  where id = v_user_id;
  if not found then raise exception using errcode = '23503', message = 'OWNER_PROFILE_MISSING'; end if;

  insert into public.organization_members(organization_id, user_id, role, is_active, is_owner)
  values (v_org_id, v_user_id, 'ADMIN', true, true);

  insert into public.staff_identities(user_id, organization_id, display_name, job_title, created_by)
  values (
    v_user_id, v_org_id,
    coalesce(nullif(btrim(v_user.raw_user_meta_data ->> 'display_name'), ''), split_part(v_user.email, '@', 1)),
    'Owner', v_user_id
  );

  insert into public.stores(organization_id, store_code, name, staff_login_mode, is_pilot_store, created_by)
  values (v_org_id, v_store_code, v_store_name, p_staff_login_mode, true, v_user_id)
  returning id into v_store_id;

  insert into public.store_memberships(store_id, organization_id, user_id, login_identifier, role, assigned_by)
  values (v_store_id, v_org_id, v_user_id, 'owner-' || v_user_id::text, 'ADMIN', v_user_id);

  insert into public.audit_logs(organization_id, entity_type, entity_id, action, new_value, user_id)
  values (
    v_org_id, 'organization', v_org_id, 'OWNER_BUSINESS_CREATED',
    jsonb_build_object('business_type', p_business_type, 'first_store_id', v_store_id, 'staff_login_mode', p_staff_login_mode),
    v_user_id
  );

  return jsonb_build_object('organization_id', v_org_id, 'store_id', v_store_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_pilot_count_session(p_store_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid := (select auth.uid()); v_org uuid; v_session uuid; v_snapshot jsonb;
begin
  select organization_id into v_org from public.stores where id=p_store_id and is_active;
  if v_org is null or not private.has_active_store_role(p_store_id,array['ADMIN','SUPERVISOR']::public.app_role[]) then
    raise exception using errcode='42501',message='STORE_MANAGER_REQUIRED';
  end if;
  if not exists(select 1 from public.count_zones where store_id=p_store_id and is_active) then
    raise exception using errcode='22023',message='COUNT_ZONE_REQUIRED';
  end if;
  if exists(select 1 from public.count_zones z where z.store_id=p_store_id and z.is_active
    and not exists(select 1 from public.zone_products zp where zp.zone_id=z.id)) then
    raise exception using errcode='22023',message='ZONE_PRODUCTS_REQUIRED';
  end if;
  if exists(select 1 from public.zone_products zp join public.count_zones z on z.id=zp.zone_id
    where z.store_id=p_store_id and not exists(select 1 from public.store_product_opening_balances b
      where b.store_id=p_store_id and b.product_id=zp.product_id)) then
    raise exception using errcode='22023',message='OPENING_BALANCE_REQUIRED';
  end if;
  if exists(select 1 from public.inventory_count_sessions where store_id=p_store_id and status in('DRAFT','IN_PROGRESS','REVIEWING')) then
    raise exception using errcode='22023',message='ACTIVE_COUNT_SESSION_EXISTS';
  end if;
  select jsonb_build_object('created_at',now(),'zones',coalesce(jsonb_agg(jsonb_build_object(
    'zone_id',z.id,'zone_name',z.name,'product_id',p.id,'product_code',p.product_code,
    'product_name',p.name,'unit',zp.count_unit) order by z.sort_order,zp.sort_order),'[]'::jsonb))
  into v_snapshot
  from public.count_zones z join public.zone_products zp on zp.zone_id=z.id
  join public.products p on p.id=zp.product_id where z.store_id=p_store_id and z.is_active and p.is_active;
  insert into public.inventory_count_sessions(organization_id,store_id,started_by,status,snapshot)
  values(v_org,p_store_id,v_user,'IN_PROGRESS',v_snapshot) returning id into v_session;
  insert into public.count_zone_progress(organization_id,session_id,zone_id,status)
  select v_org,v_session,id,'NOT_STARTED' from public.count_zones where store_id=p_store_id and is_active;
  insert into public.audit_logs(organization_id,entity_type,entity_id,action,new_value,user_id)
  values(v_org,'inventory_count_session',v_session,'COUNT_SESSION_CREATED',jsonb_build_object('store_id',p_store_id),v_user);
  return v_session;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_pilot_product(p_store_id uuid, p_product_code text, p_name text, p_count_unit text, p_purchase_unit text, p_opening_quantity numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := (select auth.uid());
  v_org uuid;
  v_product uuid;
begin
  select organization_id into v_org from public.stores where id = p_store_id and is_active;
  if v_org is null or not private.has_active_store_role(p_store_id, array['ADMIN','SUPERVISOR']::public.app_role[]) then
    raise exception using errcode = '42501', message = 'STORE_MANAGER_REQUIRED';
  end if;
  if btrim(coalesce(p_product_code,'')) = '' or btrim(coalesce(p_name,'')) = ''
    or btrim(coalesce(p_count_unit,'')) = '' or btrim(coalesce(p_purchase_unit,'')) = ''
    or p_opening_quantity is null or p_opening_quantity < 0 then
    raise exception using errcode = '22023', message = 'INVALID_PRODUCT_SETUP';
  end if;

  insert into public.products(
    organization_id, product_code, name, category, base_unit, count_unit
  ) values (
    v_org, upper(btrim(p_product_code)), btrim(p_name), '其他',
    btrim(p_purchase_unit), btrim(p_count_unit)
  ) returning id into v_product;

  insert into public.store_product_opening_balances(
    organization_id, store_id, product_id, quantity, unit, created_by
  ) values (v_org, p_store_id, v_product, p_opening_quantity, btrim(p_count_unit), v_user);

  insert into public.audit_logs(organization_id,entity_type,entity_id,action,new_value,user_id)
  values (v_org,'product',v_product,'PILOT_PRODUCT_CREATED',jsonb_build_object(
    'store_id',p_store_id,'product_code',upper(btrim(p_product_code)),
    'opening_quantity',p_opening_quantity
  ),v_user);
  return v_product;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_pilot_zone(p_store_id uuid, p_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid := (select auth.uid()); v_org uuid; v_zone uuid; v_sort integer;
begin
  select organization_id into v_org from public.stores where id=p_store_id and is_active;
  if v_org is null or not private.has_active_store_role(p_store_id,array['ADMIN','SUPERVISOR']::public.app_role[]) then
    raise exception using errcode='42501',message='STORE_MANAGER_REQUIRED';
  end if;
  if btrim(coalesce(p_name,''))='' then raise exception using errcode='22023',message='ZONE_NAME_REQUIRED'; end if;
  select coalesce(max(sort_order),-1)+1 into v_sort from public.count_zones where store_id=p_store_id;
  insert into public.count_zones(organization_id,store_id,name,sort_order)
  values(v_org,p_store_id,btrim(p_name),v_sort) returning id into v_zone;
  insert into public.audit_logs(organization_id,entity_type,entity_id,action,new_value,user_id)
  values(v_org,'count_zone',v_zone,'PILOT_ZONE_CREATED',jsonb_build_object('store_id',p_store_id,'name',btrim(p_name)),v_user);
  return v_zone;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_receipt_ocr_run(p_organization_id uuid, p_batch_id uuid, p_provider text, p_model text, p_prompt_version text, p_started_by uuid)
 RETURNS TABLE(id uuid, version integer)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_run_id uuid;
  v_version integer;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_batch_id::text, 0));

  if not exists (
    select 1
    from public.receipt_upload_batches b
    where b.id = p_batch_id
      and b.organization_id = p_organization_id
  ) then
    raise exception 'Receipt upload batch does not belong to the organization';
  end if;

  select coalesce(max(r.version), 0) + 1
  into v_version
  from public.receipt_ocr_runs r
  where r.batch_id = p_batch_id;

  insert into public.receipt_ocr_runs (
    organization_id,
    batch_id,
    version,
    provider,
    model,
    prompt_version,
    status,
    started_by
  ) values (
    p_organization_id,
    p_batch_id,
    v_version,
    p_provider,
    p_model,
    p_prompt_version,
    'PROCESSING',
    p_started_by
  ) returning receipt_ocr_runs.id into v_run_id;

  update public.receipt_upload_batches b
  set status = 'PROCESSING'
  where b.id = p_batch_id
    and b.organization_id = p_organization_id;

  if not found then
    raise exception 'Failed to mark receipt upload batch PROCESSING';
  end if;

  return query select v_run_id, v_version;
end;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_receipt_ocr(p_batch_id uuid)
 RETURNS receipt_ocr_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := (select auth.uid());
  v_org_id uuid;
  v_role text;
  v_uploaded_by uuid;
  v_job public.receipt_ocr_jobs;
begin
  select p.organization_id, p.role
  into v_org_id, v_role
  from public.profiles p
  where p.id = v_user_id;

  if v_org_id is null then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  select b.uploaded_by into v_uploaded_by
  from public.receipt_upload_batches b
  where b.id = p_batch_id and b.organization_id = v_org_id;

  if v_uploaded_by is null then
    raise exception 'BATCH_NOT_FOUND';
  end if;
  if v_role <> 'ADMIN' and v_uploaded_by <> v_user_id then
    raise exception 'FORBIDDEN';
  end if;
  if not exists (
    select 1 from public.receipt_documents d
    where d.batch_id = p_batch_id and d.organization_id = v_org_id
  ) then
    raise exception 'NO_DOCUMENTS';
  end if;

  select j.* into v_job
  from public.receipt_ocr_jobs j
  where j.batch_id = p_batch_id and j.status in ('QUEUED', 'RUNNING');
  if found then
    return v_job;
  end if;

  insert into public.receipt_ocr_jobs (
    organization_id, batch_id, requested_by
  ) values (
    v_org_id, p_batch_id, v_user_id
  ) returning * into v_job;

  update public.receipt_upload_batches
  set status = 'PROCESSING'
  where id = p_batch_id and status <> 'COMPLETED';

  return v_job;
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_goods_receipt(p_batch_id uuid, p_supplier_id uuid, p_receipt_date date, p_document_number text, p_subtotal_ex_tax numeric, p_tax numeric, p_total_inc_tax numeric, p_lines jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_org_id uuid := public.current_organization_id();
  v_receipt_id uuid;
  v_run_id uuid;
  v_line jsonb;
  v_line_count integer;
  v_line_subtotal numeric;
  v_line_tax numeric;
  v_line_total numeric;
  v_sum_subtotal numeric := 0;
  v_sum_tax numeric := 0;
  v_sum_total numeric := 0;
begin
  if not public.is_admin() then
    raise exception 'Only ADMIN can finalize a goods receipt';
  end if;

  -- Serializes retries and double-clicks for the same upload batch.
  perform pg_advisory_xact_lock(hashtextextended(p_batch_id::text, 0));

  select id into v_receipt_id
  from public.goods_receipts
  where source_batch_id = p_batch_id and organization_id = v_org_id;
  if v_receipt_id is not null then
    return v_receipt_id;
  end if;

  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'At least one receipt line is required';
  end if;
  if not exists (
    select 1 from public.receipt_upload_batches
    where id = p_batch_id and organization_id = v_org_id and status <> 'COMPLETED'
  ) then
    raise exception 'Receipt upload batch is missing or already completed';
  end if;
  if p_supplier_id is not null and not exists (
    select 1 from public.suppliers where id = p_supplier_id and organization_id = v_org_id
  ) then
    raise exception 'Supplier does not belong to this organization';
  end if;

  select id into v_run_id
  from public.receipt_ocr_runs
  where batch_id = p_batch_id and organization_id = v_org_id and status = 'SUCCEEDED'
  order by version desc limit 1;
  if v_run_id is null then
    raise exception 'A successful real OCR run is required';
  end if;

  if exists (
    select 1
    from public.receipt_ocr_fields f
    where f.ocr_run_id = v_run_id
      and f.review_status <> 'TRUSTED'
      and not exists (
        select 1 from public.receipt_review_corrections c where c.ocr_field_id = f.id
      )
  ) then
    raise exception 'All REVIEW and UNREADABLE fields require a saved human correction';
  end if;

  select count(distinct row_key) into v_line_count
  from public.receipt_ocr_fields
  where ocr_run_id = v_run_id and row_key <> 'document';
  if v_line_count <> jsonb_array_length(p_lines) then
    raise exception 'Submitted lines do not match the latest OCR run';
  end if;
  if exists (
    select 1
    from (select distinct row_key from public.receipt_ocr_fields where ocr_run_id = v_run_id and row_key <> 'document') rows
    where not exists (
      select 1 from public.receipt_product_mappings m
      where m.batch_id = p_batch_id and m.row_key = rows.row_key and m.organization_id = v_org_id
    )
  ) then
    raise exception 'Every OCR line must be mapped to a product';
  end if;

  for v_line in select value from jsonb_array_elements(p_lines)
  loop
    if nullif(v_line->>'product_id', '') is null or not exists (
      select 1 from public.products
      where id = (v_line->>'product_id')::uuid and organization_id = v_org_id
    ) then
      raise exception 'Receipt product does not belong to this organization';
    end if;
    if nullif(v_line->>'supplier_id', '') is not null and not exists (
      select 1 from public.suppliers
      where id = (v_line->>'supplier_id')::uuid and organization_id = v_org_id
    ) then
      raise exception 'Receipt line supplier does not belong to this organization';
    end if;
    if nullif(v_line->>'quantity', '') is null or (v_line->>'quantity')::numeric <= 0 then
      raise exception 'Receipt quantity must be greater than zero';
    end if;
    if nullif(v_line->>'unit', '') is null then
      raise exception 'Receipt unit is required';
    end if;

    v_line_subtotal := nullif(v_line->>'line_subtotal_ex_tax', '')::numeric;
    v_line_tax := nullif(v_line->>'tax', '')::numeric;
    v_line_total := nullif(v_line->>'line_total_inc_tax', '')::numeric;
    if v_line_subtotal is not null
      and nullif(v_line->>'unit_price_ex_tax', '') is not null
      and abs(((v_line->>'quantity')::numeric * (v_line->>'unit_price_ex_tax')::numeric) - v_line_subtotal) > greatest(1, abs(v_line_subtotal) * 0.01) then
      raise exception 'Receipt line arithmetic is inconsistent';
    end if;
    if v_line_subtotal is not null and v_line_tax is not null and v_line_total is not null
      and abs((v_line_subtotal + v_line_tax) - v_line_total) > 1 then
      raise exception 'Receipt line tax arithmetic is inconsistent';
    end if;
    v_sum_subtotal := v_sum_subtotal + coalesce(v_line_subtotal, 0);
    v_sum_tax := v_sum_tax + coalesce(v_line_tax, 0);
    v_sum_total := v_sum_total + coalesce(v_line_total, coalesce(v_line_subtotal, 0) + coalesce(v_line_tax, 0));
  end loop;

  if abs(v_sum_subtotal - coalesce(p_subtotal_ex_tax, 0)) > 1
    or abs(v_sum_tax - coalesce(p_tax, 0)) > 1
    or abs(v_sum_total - coalesce(p_total_inc_tax, 0)) > 1 then
    raise exception 'Receipt totals do not match submitted lines';
  end if;

  insert into public.goods_receipts (
    organization_id, supplier_id, receipt_date, document_number,
    subtotal_ex_tax, tax, total_inc_tax, reviewed_by, source_batch_id
  ) values (
    v_org_id, p_supplier_id, p_receipt_date, nullif(p_document_number, ''),
    p_subtotal_ex_tax, p_tax, p_total_inc_tax, (select auth.uid()), p_batch_id
  ) returning id into v_receipt_id;

  for v_line in select value from jsonb_array_elements(p_lines)
  loop
    insert into public.receipt_lines (
      organization_id, receipt_id, product_id, supplier_id, specification,
      quantity, unit, unit_price_ex_tax, line_subtotal_ex_tax, tax_rate,
      tax, line_total_inc_tax, batch_or_expiry, storage_location
    ) values (
      v_org_id, v_receipt_id, (v_line->>'product_id')::uuid,
      coalesce(nullif(v_line->>'supplier_id', '')::uuid, p_supplier_id),
      coalesce(v_line->>'specification', ''), (v_line->>'quantity')::numeric,
      v_line->>'unit', nullif(v_line->>'unit_price_ex_tax', '')::numeric,
      nullif(v_line->>'line_subtotal_ex_tax', '')::numeric,
      nullif(v_line->>'tax_rate', '')::numeric, nullif(v_line->>'tax', '')::numeric,
      nullif(v_line->>'line_total_inc_tax', '')::numeric,
      nullif(v_line->>'batch_or_expiry', ''), nullif(v_line->>'storage_location', '')
    );
  end loop;

  update public.receipt_upload_batches set status = 'COMPLETED'
  where id = p_batch_id and organization_id = v_org_id;

  insert into public.audit_logs (
    organization_id, entity_type, entity_id, action, old_value, new_value, user_id
  ) values (
    v_org_id, 'goods_receipt', v_receipt_id, 'RECEIPT_FINALIZED', null,
    jsonb_build_object('batch_id', p_batch_id, 'ocr_run_id', v_run_id,
      'subtotal_ex_tax', p_subtotal_ex_tax, 'tax', p_tax, 'total_inc_tax', p_total_inc_tax),
    (select auth.uid())
  );

  return v_receipt_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.import_catalog_products(p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_org_id uuid := public.current_organization_id();
  v_row jsonb;
  v_results jsonb := '[]'::jsonb;
  v_index integer := 1;
  v_code text;
  v_existing uuid;
  v_product_id uuid;
begin
  if not public.is_admin() then raise exception 'Only ADMIN can import products'; end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 or jsonb_array_length(p_rows) > 500 then
    raise exception 'Import requires 1 to 500 rows';
  end if;
  for v_row in select value from jsonb_array_elements(p_rows)
  loop
    v_code := nullif(btrim(v_row->>'product_code'), '');
    if nullif(btrim(v_row->>'name'), '') is null
      or nullif(btrim(v_row->>'base_unit'), '') is null
      or nullif(btrim(v_row->>'count_unit'), '') is null then
      v_results := v_results || jsonb_build_array(jsonb_build_object('row', v_index, 'status', 'ERROR', 'message', '缺少必填欄位'));
    else
      select id into v_existing from public.products
      where organization_id = v_org_id and (
        (v_code is not null and product_code = v_code)
        or (lower(name) = lower(btrim(v_row->>'name')) and lower(specification) = lower(coalesce(btrim(v_row->>'specification'), '')))
      ) limit 1;
      if v_existing is not null then
        v_results := v_results || jsonb_build_array(jsonb_build_object('row', v_index, 'status', 'DUPLICATE', 'product_id', v_existing));
      else
        insert into public.products (
          organization_id, product_code, name, specification, category, base_unit, count_unit, current_supplier_id
        ) values (
          v_org_id, coalesce(v_code, 'PF-' || upper(substr(gen_random_uuid()::text, 1, 8))),
          btrim(v_row->>'name'), coalesce(btrim(v_row->>'specification'), ''),
          case when v_row->>'category' in ('海鮮','牛肉','豬肉','雞肉','乳製品','蔬菜','水果','乾貨','醬料／調味','酒水','包材／耗材','其他') then v_row->>'category' else '其他' end,
          btrim(v_row->>'base_unit'), btrim(v_row->>'count_unit'),
          (select s.id from public.suppliers s where s.organization_id = v_org_id and s.supplier_code = nullif(btrim(v_row->>'supplier_code'), '') limit 1)
        ) returning id into v_product_id;
        insert into public.audit_logs (organization_id, entity_type, entity_id, action, old_value, new_value, user_id)
        values (v_org_id, 'product', v_product_id, 'PRODUCT_IMPORTED', null, v_row, (select auth.uid()));
        v_results := v_results || jsonb_build_array(jsonb_build_object('row', v_index, 'status', 'IMPORTED', 'product_id', v_product_id));
      end if;
    end if;
    v_index := v_index + 1;
    v_existing := null;
  end loop;
  return v_results;
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_pilot_count_discrepancy(p_discrepancy_id uuid, p_reason text, p_action text, p_quantity numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid := (select auth.uid()); v_org uuid; v_store uuid; v_session uuid; v_zone uuid;
  v_product uuid; v_initial uuid; v_unit text; v_entry uuid;
begin
  select d.organization_id,s.store_id,d.session_id,d.zone_id,d.product_id,d.initial_entry_id,e.unit
  into v_org,v_store,v_session,v_zone,v_product,v_initial,v_unit
  from public.inventory_count_discrepancies d join public.inventory_count_sessions s on s.id=d.session_id
  join public.count_entries e on e.id=d.initial_entry_id where d.id=p_discrepancy_id and d.status='PENDING';
  if v_store is null or not private.has_active_store_role(v_store,array['ADMIN','SUPERVISOR']::public.app_role[]) then
    raise exception using errcode='42501',message='STORE_MANAGER_REQUIRED';
  end if;
  if p_reason not in('INPUT_ERROR','MISSED_OR_WRONG_ZONE','WASTE_NOT_RECORDED','TRANSFER_NOT_RECORDED','RECEIPT_NOT_RECORDED','OTHER')
    or p_action not in('CORRECTION','RECOUNT') or p_quantity is null or p_quantity<0 then
    raise exception using errcode='22023',message='INVALID_COUNT_RESOLUTION';
  end if;
  insert into public.count_entries(organization_id,session_id,zone_id,product_id,quantity,unit,entered_by,entry_type,parent_entry_id)
  values(v_org,v_session,v_zone,v_product,p_quantity,v_unit,v_user,p_action,v_initial) returning id into v_entry;
  insert into public.inventory_count_resolution_events(
    organization_id,store_id,discrepancy_id,action,reason,original_entry_id,resulting_entry_id,created_by
  ) values(v_org,v_store,p_discrepancy_id,p_action,p_reason,v_initial,v_entry,v_user);
  update public.inventory_count_discrepancies set final_entry_id=v_entry,reason=p_reason,status='RESOLVED',answered_by=v_user,answered_at=now()
  where id=p_discrepancy_id;
  insert into public.audit_logs(organization_id,entity_type,entity_id,action,old_value,new_value,user_id)
  select v_org,'inventory_count_discrepancy',p_discrepancy_id,'COUNT_DISCREPANCY_RESOLVED',
    jsonb_build_object('initial_entry_id',v_initial),jsonb_build_object('resulting_entry_id',v_entry,'reason',p_reason,'action',p_action),v_user;
  if not exists(select 1 from public.inventory_count_discrepancies where session_id=v_session and status='PENDING') then
    update public.inventory_count_sessions set status='CLOSED' where id=v_session;
  end if;
  return v_entry;
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_staff_pin(p_user_id uuid, p_pin text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_pin !~ '^[0-9]{6}$' then
    raise exception using errcode = '22023', message = 'PIN_MUST_BE_SIX_DIGITS';
  end if;

  if not exists (
    select 1 from public.staff_identities si
    where si.user_id = p_user_id and si.is_active
  ) then
    raise exception using errcode = '22023', message = 'ACTIVE_STAFF_REQUIRED';
  end if;

  insert into private.staff_pin_credentials(user_id, pin_hash)
  values (p_user_id, extensions.crypt(p_pin, extensions.gen_salt('bf', 12)))
  on conflict (user_id) do update set
    pin_hash = excluded.pin_hash,
    failed_attempts = 0,
    locked_until = null,
    pin_changed_at = now(),
    updated_at = now();
end;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.verify_staff_pin(p_store_code text, p_identifier text, p_pin text)
 RETURNS TABLE(outcome text, user_id uuid, auth_email text, organization_id uuid, store_id uuid, role app_role, locked_until timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_store public.stores%rowtype;
  v_staff public.staff_identities%rowtype;
  v_membership public.store_memberships%rowtype;
  v_credential private.staff_pin_credentials%rowtype;
  v_email text;
  v_identifier_hash text := encode(extensions.digest(lower(btrim(coalesce(p_identifier, ''))), 'sha256'), 'hex');
begin
  select * into v_store
  from public.stores s
  where lower(s.store_code) = lower(btrim(p_store_code)) and s.is_active
  limit 1;

  if v_store.id is null then
    insert into private.staff_login_attempts(identifier_hash, was_successful, outcome)
    values (v_identifier_hash, false, 'INVALID');
    return query select 'INVALID'::text, null::uuid, null::text, null::uuid, null::uuid, null::public.app_role, null::timestamptz;
    return;
  end if;

  select sm.* into v_membership
  from public.store_memberships sm
  where sm.store_id = v_store.id and lower(sm.login_identifier) = lower(btrim(p_identifier))
  limit 1;

  if v_membership.user_id is not null then
    select si.* into v_staff
    from public.staff_identities si
    where si.user_id = v_membership.user_id and si.organization_id = v_membership.organization_id;
  end if;

  if v_staff.user_id is null or not v_staff.is_active or not v_membership.is_active then
    insert into private.staff_login_attempts(user_id, store_id, identifier_hash, was_successful, outcome)
    values (v_staff.user_id, v_store.id, v_identifier_hash, false,
      case when v_staff.user_id is null then 'INVALID' else 'INACTIVE' end);
    return query select 'INVALID'::text, null::uuid, null::text, null::uuid, v_store.id, null::public.app_role, null::timestamptz;
    return;
  end if;

  select * into v_credential
  from private.staff_pin_credentials c
  where c.user_id = v_staff.user_id
  for update;

  if v_credential.user_id is null then
    insert into private.staff_login_attempts(user_id, store_id, identifier_hash, was_successful, outcome)
    values (v_staff.user_id, v_store.id, v_identifier_hash, false, 'INVALID');
    return query select 'INVALID'::text, null::uuid, null::text, v_store.organization_id, v_store.id, null::public.app_role, null::timestamptz;
    return;
  end if;

  if v_credential.locked_until is not null and v_credential.locked_until > now() then
    insert into private.staff_login_attempts(user_id, store_id, identifier_hash, was_successful, outcome)
    values (v_staff.user_id, v_store.id, v_identifier_hash, false, 'LOCKED');
    return query select 'LOCKED'::text, null::uuid, null::text, v_store.organization_id, v_store.id, v_membership.role, v_credential.locked_until;
    return;
  end if;

  if extensions.crypt(p_pin, v_credential.pin_hash) <> v_credential.pin_hash then
    update private.staff_pin_credentials c set
      failed_attempts = least(5, c.failed_attempts + 1),
      locked_until = case when c.failed_attempts + 1 >= 5 then now() + interval '15 minutes' else null end,
      updated_at = now()
    where c.user_id = v_staff.user_id
    returning c.locked_until into v_credential.locked_until;

    insert into private.staff_login_attempts(user_id, store_id, identifier_hash, was_successful, outcome)
    values (v_staff.user_id, v_store.id, v_identifier_hash, false,
      case when v_credential.locked_until is null then 'INVALID' else 'LOCKED' end);
    return query select
      case when v_credential.locked_until is null then 'INVALID' else 'LOCKED' end,
      null::uuid, null::text, v_store.organization_id, v_store.id, v_membership.role, v_credential.locked_until;
    return;
  end if;

  update private.staff_pin_credentials c
  set failed_attempts = 0, locked_until = null, updated_at = now()
  where c.user_id = v_staff.user_id;

  select u.email into v_email from auth.users u where u.id = v_staff.user_id;
  insert into private.staff_login_attempts(user_id, store_id, identifier_hash, was_successful, outcome)
  values (v_staff.user_id, v_store.id, v_identifier_hash, true, 'OK');

  return query select 'OK'::text, v_staff.user_id, v_email, v_store.organization_id,
    v_store.id, v_membership.role, null::timestamptz;
end;
$function$
